// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {keepMyEther} from "../src/keepMyEther.sol";

contract InvMutTest is Test {
    keepMyEther c;
    function setUp() public { c = new keepMyEther(); }
    function testFuzz_property(address actor, uint256 amount) public {
        vm.assume(actor != address(0));
        vm.assume(amount > 0 && amount <= type(uint256).max / 2);
        vm.deal(actor, amount);
        vm.prank(actor);
        (bool funded,) = address(c).call{value: amount}("");
        require(funded, "funding failed");
        vm.prank(actor);
        c.withdraw();
        assertTrue(c.balances(actor) == 0);
    }
}
